// generated by tools/build_verse_manifests.js from dc_english.js — Dual-view English for the chapters of dc_verses/dc51_60.js
registerEnglish([["D&C",51,1,"Hearken unto me, saith the Lord your God, and I will speak unto my servant Edward Partridge, and give unto him directions; for it must needs be that he receive directions how to organize this people."],["D&C",51,2,"For it must needs be that they be organized according to my laws; if otherwise, they will be cut off."],["D&C",51,3,"Wherefore, let my servant Edward Partridge, and those whom he has chosen, in whom I am well pleased, appoint unto this people their portions, every man equal according to his family, according to his circumstances and his wants and needs."],["D&C",51,4,"And let my servant Edward Partridge, when he shall appoint a man his portion, give unto him a writing that shall secure unto him his portion, that he shall hold it, even this right and this inheritance in the church, until he transgresses and is not accounted worthy by the voice of the church, according to the laws and covenants of the church, to belong to the church."],["D&C",51,5,"And if he shall transgress and is not accounted worthy to belong to the church, he shall not have power to claim that portion which he has consecrated unto the bishop for the poor and needy of my church; therefore, he shall not retain the gift, but shall only have claim on that portion that is deeded unto him."],["D&C",51,6,"And thus all things shall be made sure, according to the laws of the land."],["D&C",51,7,"And let that which belongs to this people be appointed unto this people."],["D&C",51,8,"And the money which is left unto this people—let there be an agent appointed unto this people, to take the money to provide food and raiment, according to the wants of this people."],["D&C",51,9,"And let every man deal honestly, and be alike among this people, and receive alike, that ye may be one, even as I have commanded you."],["D&C",51,10,"And let that which belongeth to this people not be taken and given unto that of another church."],["D&C",51,11,"Wherefore, if another church would receive money of this church, let them pay unto this church again according as they shall agree;"],["D&C",51,12,"And this shall be done through the bishop or the agent, which shall be appointed by the voice of the church."],["D&C",51,13,"And again, let the bishop appoint a storehouse unto this church; and let all things both in money and in meat, which are more than is needful for the wants of this people, be kept in the hands of the bishop."],["D&C",51,14,"And let him also reserve unto himself for his own wants, and for the wants of his family, as he shall be employed in doing this business."],["D&C",51,15,"And thus I grant unto this people a privilege of organizing themselves according to my laws."],["D&C",51,16,"And I consecrate unto them this land for a little season, until I, the Lord, shall provide for them otherwise, and command them to go hence;"],["D&C",51,17,"And the hour and the day is not given unto them, wherefore let them act upon this land as for years, and this shall turn unto them for their good."],["D&C",51,18,"Behold, this shall be an example unto my servant Edward Partridge, in other places, in all churches."],["D&C",51,19,"And whoso is found a faithful, a just, and a wise steward shall enter into the joy of his Lord, and shall inherit eternal life."],["D&C",51,20,"Verily, I say unto you, I am Jesus Christ, who cometh quickly, in an hour you think not. Even so. Amen."],["D&C",52,1,"Behold, thus saith the Lord unto the elders whom he hath called and chosen in these last days, by the voice of his Spirit—"],["D&C",52,2,"Saying: I, the Lord, will make known unto you what I will that ye shall do from this time until the next conference, which shall be held in Missouri, upon the land which I will consecrate unto my people, which are a remnant of Jacob, and those who are heirs according to the covenant."],["D&C",52,3,"Wherefore, verily I say unto you, let my servants Joseph Smith, Jun., and Sidney Rigdon take their journey as soon as preparations can be made to leave their homes, and journey to the land of Missouri."],["D&C",52,4,"And inasmuch as they are faithful unto me, it shall be made known unto them what they shall do;"],["D&C",52,5,"And it shall also, inasmuch as they are faithful, be made known unto them the land of your inheritance."],["D&C",52,6,"And inasmuch as they are not faithful, they shall be cut off, even as I will, as seemeth me good."],["D&C",52,7,"And again, verily I say unto you, let my servant Lyman Wight and my servant John Corrill take their journey speedily;"],["D&C",52,8,"And also my servant John Murdock, and my servant Hyrum Smith, take their journey unto the same place by the way of Detroit."],["D&C",52,9,"And let them journey from thence preaching the word by the way, saying none other things than that which the prophets and apostles have written, and that which is taught them by the Comforter through the prayer of faith."],["D&C",52,10,"Let them go two by two, and thus let them preach by the way in every congregation, baptizing by water, and the laying on of the hands by the water's side."],["D&C",52,11,"For thus saith the Lord, I will cut my work short in righteousness, for the days come that I will send forth judgment unto victory."],["D&C",52,12,"And let my servant Lyman Wight beware, for Satan desireth to sift him as chaff."],["D&C",52,13,"And behold, he that is faithful shall be made ruler over many things."],["D&C",52,14,"And again, I will give unto you a pattern in all things, that ye may not be deceived; for Satan is abroad in the land, and he goeth forth deceiving the nations—"],["D&C",52,15,"Wherefore he that prayeth, whose spirit is contrite, the same is accepted of me if he obey mine ordinances."],["D&C",52,16,"He that speaketh, whose spirit is contrite, whose language is meek and edifieth, the same is of God if he obey mine ordinances."],["D&C",52,17,"And again, he that trembleth under my power shall be made strong, and shall bring forth fruits of praise and wisdom, according to the revelations and truths which I have given you."],["D&C",52,18,"And again, he that is overcome and bringeth not forth fruits, even according to this pattern, is not of me."],["D&C",52,19,"Wherefore, by this pattern ye shall know the spirits in all cases under the whole heavens."],["D&C",52,20,"And the days have come; according to men's faith it shall be done unto them."],["D&C",52,21,"Behold, this commandment is given unto all the elders whom I have chosen."],["D&C",52,22,"And again, verily I say unto you, let my servant Thomas B. Marsh and my servant Ezra Thayre take their journey also, preaching the word by the way unto this same land."],["D&C",52,23,"And again, let my servant Isaac Morley and my servant Ezra Booth take their journey, also preaching the word by the way unto this same land."],["D&C",52,24,"And again, let my servants Edward Partridge and Martin Harris take their journey with my servants Sidney Rigdon and Joseph Smith, Jun."],["D&C",52,25,"Let my servants David Whitmer and Harvey Whitlock also take their journey, and preach by the way unto this same land."],["D&C",52,26,"And let my servants Parley P. Pratt and Orson Pratt take their journey, and preach by the way, even unto this same land."],["D&C",52,27,"And let my servants Solomon Hancock and Simeon Carter also take their journey unto this same land, and preach by the way."],["D&C",52,28,"Let my servants Edson Fuller and Jacob Scott also take their journey."],["D&C",52,29,"Let my servants Levi W. Hancock and Zebedee Coltrin also take their journey."],["D&C",52,30,"Let my servants Reynolds Cahoon and Samuel H. Smith also take their journey."],["D&C",52,31,"Let my servants Wheeler Baldwin and William Carter also take their journey."],["D&C",52,32,"And let my servants Newel Knight and Selah J. Griffin both be ordained, and also take their journey."],["D&C",52,33,"Yea, verily I say, let all these take their journey unto one place, in their several courses, and one man shall not build upon another's foundation, neither journey in another's track."],["D&C",52,34,"He that is faithful, the same shall be kept and blessed with much fruit."],["D&C",52,35,"And again, I say unto you, let my servants Joseph Wakefield and Solomon Humphrey take their journey into the eastern lands;"],["D&C",52,36,"Let them labor with their families, declaring none other things than the prophets and apostles, that which they have seen and heard and most assuredly believe, that the prophecies may be fulfilled."],["D&C",52,37,"In consequence of transgression, let that which was bestowed upon Heman Basset be taken from him, and placed upon the head of Simonds Ryder."],["D&C",52,38,"And again, verily I say unto you, let Jared Carter be ordained a priest, and also George James be ordained a priest."],["D&C",52,39,"Let the residue of the elders watch over the churches, and declare the word in the regions round about them; and let them labor with their own hands that there be no idolatry nor wickedness practiced."],["D&C",52,40,"And remember in all things the poor and the needy, the sick and the afflicted, for he that doeth not these things, the same is not my disciple."],["D&C",52,41,"And again, let my servants Joseph Smith, Jun., and Sidney Rigdon and Edward Partridge take with them a recommend from the church. And let there be one obtained for my servant Oliver Cowdery also."],["D&C",52,42,"And thus, even as I have said, if ye are faithful ye shall assemble yourselves together to rejoice upon the land of Missouri, which is the land of your inheritance, which is now the land of your enemies."],["D&C",52,43,"But, behold, I, the Lord, will hasten the city in its time, and will crown the faithful with joy and with rejoicing."],["D&C",52,44,"Behold, I am Jesus Christ, the Son of God, and I will lift them up at the last day. Even so. Amen."],["D&C",53,1,"Behold, I say unto you, my servant Sidney Gilbert, that I have heard your prayers; and you have called upon me that it should be made known unto you, of the Lord your God, concerning your calling and election in the church, which I, the Lord, have raised up in these last days."],["D&C",53,2,"Behold, I, the Lord, who was crucified for the sins of the world, give unto you a commandment that you shall forsake the world."],["D&C",53,3,"Take upon you mine ordination, even that of an elder, to preach faith and repentance and remission of sins, according to my word, and the reception of the Holy Spirit by the laying on of hands;"],["D&C",53,4,"And also to be an agent unto this church in the place which shall be appointed by the bishop, according to commandments which shall be given hereafter."],["D&C",53,5,"And again, verily I say unto you, you shall take your journey with my servants Joseph Smith, Jun., and Sidney Rigdon."],["D&C",53,6,"Behold, these are the first ordinances which you shall receive; and the residue shall be made known in a time to come, according to your labor in my vineyard."],["D&C",53,7,"And again, I would that ye should learn that he only is saved who endureth unto the end. Even so. Amen."],["D&C",54,1,"Behold, thus saith the Lord, even Alpha and Omega, the beginning and the end, even he who was crucified for the sins of the world—"],["D&C",54,2,"Behold, verily, verily, I say unto you, my servant Newel Knight, you shall stand fast in the office whereunto I have appointed you."],["D&C",54,3,"And if your brethren desire to escape their enemies, let them repent of all their sins, and become truly humble before me and contrite."],["D&C",54,4,"And as the covenant which they made unto me has been broken, even so it has become void and of none effect."],["D&C",54,5,"And wo to him by whom this offense cometh, for it had been better for him that he had been drowned in the depth of the sea."],["D&C",54,6,"But blessed are they who have kept the covenant and observed the commandment, for they shall obtain mercy."],["D&C",54,7,"Wherefore, go to now and flee the land, lest your enemies come upon you; and take your journey, and appoint whom you will to be your leader, and to pay moneys for you."],["D&C",54,8,"And thus you shall take your journey into the regions westward, unto the land of Missouri, unto the borders of the Lamanites."],["D&C",54,9,"And after you have done journeying, behold, I say unto you, seek ye a living like unto men, until I prepare a place for you."],["D&C",54,10,"And again, be patient in tribulation until I come; and, behold, I come quickly, and my reward is with me, and they who have sought me early shall find rest to their souls. Even so. Amen."],["D&C",55,1,"Behold, thus saith the Lord unto you, my servant William, yea, even the Lord of the whole earth, thou art called and chosen; and after thou hast been baptized by water, which if you do with an eye single to my glory, you shall have a remission of your sins and a reception of the Holy Spirit by the laying on of hands;"],["D&C",55,2,"And then thou shalt be ordained by the hand of my servant Joseph Smith, Jun., to be an elder unto this church, to preach repentance and remission of sins by way of baptism in the name of Jesus Christ, the Son of the living God."],["D&C",55,3,"And on whomsoever you shall lay your hands, if they are contrite before me, you shall have power to give the Holy Spirit."],["D&C",55,4,"And again, you shall be ordained to assist my servant Oliver Cowdery to do the work of printing, and of selecting and writing books for schools in this church, that little children also may receive instruction before me as is pleasing unto me."],["D&C",55,5,"And again, verily I say unto you, for this cause you shall take your journey with my servants Joseph Smith, Jun., and Sidney Rigdon, that you may be planted in the land of your inheritance to do this work."],["D&C",55,6,"And again, let my servant Joseph Coe also take his journey with them. The residue shall be made known hereafter, even as I will. Amen."],["D&C",56,1,"Hearken, O ye people who profess my name, saith the Lord your God; for behold, mine anger is kindled against the rebellious, and they shall know mine arm and mine indignation, in the day of visitation and of wrath upon the nations."],["D&C",56,2,"And he that will not take up his cross and follow me, and keep my commandments, the same shall not be saved."],["D&C",56,3,"Behold, I, the Lord, command; and he that will not obey shall be cut off in mine own due time, after I have commanded and the commandment is broken."],["D&C",56,4,"Wherefore I, the Lord, command and revoke, as it seemeth me good; and all this to be answered upon the heads of the rebellious, saith the Lord."],["D&C",56,5,"Wherefore, I revoke the commandment which was given unto my servants Thomas B. Marsh and Ezra Thayre, and give a new commandment unto my servant Thomas, that he shall take up his journey speedily to the land of Missouri, and my servant Selah J. Griffin shall also go with him."],["D&C",56,6,"For behold, I revoke the commandment which was given unto my servants Selah J. Griffin and Newel Knight, in consequence of the stiffneckedness of my people which are in Thompson, and their rebellions."],["D&C",56,7,"Wherefore, let my servant Newel Knight remain with them; and as many as will go may go, that are contrite before me, and be led by him to the land which I have appointed."],["D&C",56,8,"And again, verily I say unto you, that my servant Ezra Thayre must repent of his pride, and of his selfishness, and obey the former commandment which I have given him concerning the place upon which he lives."],["D&C",56,9,"And if he will do this, as there shall be no divisions made upon the land, he shall be appointed still to go to the land of Missouri;"],["D&C",56,10,"Otherwise he shall receive the money which he has paid, and shall leave the place, and shall be cut off out of my church, saith the Lord God of hosts;"],["D&C",56,11,"And though the heaven and the earth pass away, these words shall not pass away, but shall be fulfilled."],["D&C",56,12,"And if my servant Joseph Smith, Jun., must needs pay the money, behold, I, the Lord, will pay it unto him again in the land of Missouri, that those of whom he shall receive may be rewarded again according to that which they do;"],["D&C",56,13,"For according to that which they do they shall receive, even in lands for their inheritance."],["D&C",56,14,"Behold, thus saith the Lord unto my people—you have many things to do and to repent of; for behold, your sins have come up unto me, and are not pardoned, because you seek to counsel in your own ways."],["D&C",56,15,"And your hearts are not satisfied. And ye obey not the truth, but have pleasure in unrighteousness."],["D&C",56,16,"Wo unto you rich men, that will not give your substance to the poor, for your riches will canker your souls; and this shall be your lamentation in the day of visitation, and of judgment, and of indignation: The harvest is past, the summer is ended, and my soul is not saved!"],["D&C",56,17,"Wo unto you poor men, whose hearts are not broken, whose spirits are not contrite, and whose bellies are not satisfied, and whose hands are not stayed from laying hold upon other men's goods, whose eyes are full of greediness, and who will not labor with your own hands!"],["D&C",56,18,"But blessed are the poor who are pure in heart, whose hearts are broken, and whose spirits are contrite, for they shall see the kingdom of God coming in power and great glory unto their deliverance; for the fatness of the earth shall be theirs."],["D&C",56,19,"For behold, the Lord shall come, and his recompense shall be with him, and he shall reward every man, and the poor shall rejoice;"],["D&C",56,20,"And their generations shall inherit the earth from generation to generation, forever and ever. And now I make an end of speaking unto you. Even so. Amen."],["D&C",57,1,"Hearken, O ye elders of my church, saith the Lord your God, who have assembled yourselves together, according to my commandments, in this land, which is the land of Missouri, which is the land which I have appointed and consecrated for the gathering of the saints."],["D&C",57,2,"Wherefore, this is the land of promise, and the place for the city of Zion."],["D&C",57,3,"And thus saith the Lord your God, if you will receive wisdom here is wisdom. Behold, the place which is now called Independence is the center place; and a spot for the temple is lying westward, upon a lot which is not far from the courthouse."],["D&C",57,4,"Wherefore, it is wisdom that the land should be purchased by the saints, and also every tract lying westward, even unto the line running directly between Jew and Gentile;"],["D&C",57,5,"And also every tract bordering by the prairies, inasmuch as my disciples are enabled to buy lands. Behold, this is wisdom, that they may obtain it for an everlasting inheritance."],["D&C",57,6,"And let my servant Sidney Gilbert stand in the office to which I have appointed him, to receive moneys, to be an agent unto the church, to buy land in all the regions round about, inasmuch as can be done in righteousness, and as wisdom shall direct."],["D&C",57,7,"And let my servant Edward Partridge stand in the office to which I have appointed him, and divide unto the saints their inheritance, even as I have commanded; and also those whom he has appointed to assist him."],["D&C",57,8,"And again, verily I say unto you, let my servant Sidney Gilbert plant himself in this place, and establish a store, that he may sell goods without fraud, that he may obtain money to buy lands for the good of the saints, and that he may obtain whatsoever things the disciples may need to plant them in their inheritance."],["D&C",57,9,"And also let my servant Sidney Gilbert obtain a license—behold here is wisdom, and whoso readeth let him understand—that he may send goods also unto the people, even by whom he will as clerks employed in his service;"],["D&C",57,10,"And thus provide for my saints, that my gospel may be preached unto those who sit in darkness and in the region and shadow of death."],["D&C",57,11,"And again, verily I say unto you, let my servant William W. Phelps be planted in this place, and be established as a printer unto the church."],["D&C",57,12,"And lo, if the world receive his writings—behold here is wisdom—let him obtain whatsoever he can obtain in righteousness, for the good of the saints."],["D&C",57,13,"And let my servant Oliver Cowdery assist him, even as I have commanded, in whatsoever place I shall appoint unto him, to copy, and to correct, and select, that all things may be right before me, as it shall be proved by the Spirit through him."],["D&C",57,14,"And thus let those of whom I have spoken be planted in the land of Zion, as speedily as can be, with their families, to do those things even as I have spoken."],["D&C",57,15,"And now concerning the gathering—Let the bishop and the agent make preparations for those families which have been commanded to come to this land, as soon as possible, and plant them in their inheritance."],["D&C",57,16,"And unto the residue of both elders and members further directions shall be given hereafter. Even so. Amen."],["D&C",58,1,"Hearken, O ye elders of my church, and give ear to my word, and learn of me what I will concerning you, and also concerning this land unto which I have sent you."],["D&C",58,2,"For verily I say unto you, blessed is he that keepeth my commandments, whether in life or in death; and he that is faithful in tribulation, the reward of the same is greater in the kingdom of heaven."],["D&C",58,3,"Ye cannot behold with your natural eyes, for the present time, the design of your God concerning those things which shall come hereafter, and the glory which shall follow after much tribulation."],["D&C",58,4,"For after much tribulation come the blessings. Wherefore the day cometh that ye shall be crowned with much glory; the hour is not yet, but is nigh at hand."],["D&C",58,5,"Remember this, which I tell you before, that you may lay it to heart, and receive that which is to follow."],["D&C",58,6,"Behold, verily I say unto you, for this cause I have sent you—that you might be obedient, and that your hearts might be prepared to bear testimony of the things which are to come;"],["D&C",58,7,"And also that you might be honored in laying the foundation, and in bearing record of the land upon which the Zion of God shall stand;"],["D&C",58,8,"And also that a feast of fat things might be prepared for the poor; yea, a feast of fat things, of wine on the lees well refined, that the earth may know that the mouths of the prophets shall not fail;"],["D&C",58,9,"Yea, a supper of the house of the Lord, well prepared, unto which all nations shall be invited."],["D&C",58,10,"First, the rich and the learned, the wise and the noble;"],["D&C",58,11,"And after that cometh the day of my power; then shall the poor, the lame, and the blind, and the deaf, come in unto the marriage of the Lamb, and partake of the supper of the Lord, prepared for the great day to come."],["D&C",58,12,"Behold, I, the Lord, have spoken it."],["D&C",58,13,"And that the testimony might go forth from Zion, yea, from the mouth of the city of the heritage of God—"],["D&C",58,14,"Yea, for this cause I have sent you hither, and have selected my servant Edward Partridge, and have appointed unto him his mission in this land."],["D&C",58,15,"But if he repent not of his sins, which are unbelief and blindness of heart, let him take heed lest he fall."],["D&C",58,16,"Behold his mission is given unto him, and it shall not be given again."],["D&C",58,17,"And whoso standeth in this mission is appointed to be a judge in Israel, like as it was in ancient days, to divide the lands of the heritage of God unto his children;"],["D&C",58,18,"And to judge his people by the testimony of the just, and by the assistance of his counselors, according to the laws of the kingdom which are given by the prophets of God."],["D&C",58,19,"For verily I say unto you, my law shall be kept on this land."],["D&C",58,20,"Let no man think he is ruler; but let God rule him that judgeth, according to the counsel of his own will, or, in other words, him that counseleth or sitteth upon the judgment seat."],["D&C",58,21,"Let no man break the laws of the land, for he that keepeth the laws of God hath no need to break the laws of the land."],["D&C",58,22,"Wherefore, be subject to the powers that be, until he reigns whose right it is to reign, and subdues all enemies under his feet."],["D&C",58,23,"Behold, the laws which ye have received from my hand are the laws of the church, and in this light ye shall hold them forth. Behold, here is wisdom."],["D&C",58,24,"And now, as I spake concerning my servant Edward Partridge, this land is the land of his residence, and those whom he has appointed for his counselors; and also the land of the residence of him whom I have appointed to keep my storehouse;"],["D&C",58,25,"Wherefore, let them bring their families to this land, as they shall counsel between themselves and me."],["D&C",58,26,"For behold, it is not meet that I should command in all things; for he that is compelled in all things, the same is a slothful and not a wise servant; wherefore he receiveth no reward."],["D&C",58,27,"Verily I say, men should be anxiously engaged in a good cause, and do many things of their own free will, and bring to pass much righteousness;"],["D&C",58,28,"For the power is in them, wherein they are agents unto themselves. And inasmuch as men do good they shall in nowise lose their reward."],["D&C",58,29,"But he that doeth not anything until he is commanded, and receiveth a commandment with doubtful heart, and keepeth it with slothfulness, the same is damned."],["D&C",58,30,"Who am I that made man, saith the Lord, that will hold him guiltless that obeys not my commandments?"],["D&C",58,31,"Who am I, saith the Lord, that have promised and have not fulfilled?"],["D&C",58,32,"I command and men obey not; I revoke and they receive not the blessing."],["D&C",58,33,"Then they say in their hearts: This is not the work of the Lord, for his promises are not fulfilled. But wo unto such, for their reward lurketh beneath, and not from above."],["D&C",58,34,"And now I give unto you further directions concerning this land."],["D&C",58,35,"It is wisdom in me that my servant Martin Harris should be an example unto the church, in laying his moneys before the bishop of the church."],["D&C",58,36,"And also, this is a law unto every man that cometh unto this land to receive an inheritance; and he shall do with his moneys according as the law directs."],["D&C",58,37,"And it is wisdom also that there should be lands purchased in Independence, for the place of the storehouse, and also for the house of the printing."],["D&C",58,38,"And other directions concerning my servant Martin Harris shall be given him of the Spirit, that he may receive his inheritance as seemeth him good;"],["D&C",58,39,"And let him repent of his sins, for he seeketh the praise of the world."],["D&C",58,40,"And also let my servant William W. Phelps stand in the office to which I have appointed him, and receive his inheritance in the land;"],["D&C",58,41,"And also he hath need to repent, for I, the Lord, am not well pleased with him, for he seeketh to excel, and he is not sufficiently meek before me."],["D&C",58,42,"Behold, he who has repented of his sins, the same is forgiven, and I, the Lord, remember them no more."],["D&C",58,43,"By this ye may know if a man repenteth of his sins—behold, he will confess them and forsake them."],["D&C",58,44,"And now, verily, I say concerning the residue of the elders of my church, the time has not yet come, for many years, for them to receive their inheritance in this land, except they desire it through the prayer of faith, only as it shall be appointed unto them of the Lord."],["D&C",58,45,"For, behold, they shall push the people together from the ends of the earth."],["D&C",58,46,"Wherefore, assemble yourselves together; and they who are not appointed to stay in this land, let them preach the gospel in the regions round about; and after that let them return to their homes."],["D&C",58,47,"Let them preach by the way, and bear testimony of the truth in all places, and call upon the rich, the high and the low, and the poor to repent."],["D&C",58,48,"And let them build up churches, inasmuch as the inhabitants of the earth will repent."],["D&C",58,49,"And let there be an agent appointed by the voice of the church, unto the church in Ohio, to receive moneys to purchase lands in Zion."],["D&C",58,50,"And I give unto my servant Sidney Rigdon a commandment, that he shall write a description of the land of Zion, and a statement of the will of God, as it shall be made known by the Spirit unto him;"],["D&C",58,51,"And an epistle and subscription, to be presented unto all the churches to obtain moneys, to be put into the hands of the bishop, of himself or the agent, as seemeth him good or as he shall direct, to purchase lands for an inheritance for the children of God."],["D&C",58,52,"For, behold, verily I say unto you, the Lord willeth that the disciples and the children of men should open their hearts, even to purchase this whole region of country, as soon as time will permit."],["D&C",58,53,"Behold, here is wisdom. Let them do this lest they receive none inheritance, save it be by the shedding of blood."],["D&C",58,54,"And again, inasmuch as there is land obtained, let there be workmen sent forth of all kinds unto this land, to labor for the saints of God."],["D&C",58,55,"Let all these things be done in order; and let the privileges of the lands be made known from time to time, by the bishop or the agent of the church."],["D&C",58,56,"And let the work of the gathering be not in haste, nor by flight; but let it be done as it shall be counseled by the elders of the church at the conferences, according to the knowledge which they receive from time to time."],["D&C",58,57,"And let my servant Sidney Rigdon consecrate and dedicate this land, and the spot for the temple, unto the Lord."],["D&C",58,58,"And let a conference meeting be called; and after that let my servants Sidney Rigdon and Joseph Smith, Jun., return, and also Oliver Cowdery with them, to accomplish the residue of the work which I have appointed unto them in their own land, and the residue as shall be ruled by the conferences."],["D&C",58,59,"And let no man return from this land except he bear record by the way, of that which he knows and most assuredly believes."],["D&C",58,60,"Let that which has been bestowed upon Ziba Peterson be taken from him; and let him stand as a member in the church, and labor with his own hands, with the brethren, until he is sufficiently chastened for all his sins; for he confesseth them not, and he thinketh to hide them."],["D&C",58,61,"Let the residue of the elders of this church, who are coming to this land, some of whom are exceedingly blessed even above measure, also hold a conference upon this land."],["D&C",58,62,"And let my servant Edward Partridge direct the conference which shall be held by them."],["D&C",58,63,"And let them also return, preaching the gospel by the way, bearing record of the things which are revealed unto them."],["D&C",58,64,"For, verily, the sound must go forth from this place into all the world, and unto the uttermost parts of the earth—the gospel must be preached unto every creature, with signs following them that believe."],["D&C",58,65,"And behold the Son of Man cometh. Amen."],["D&C",59,1,"Behold, blessed, saith the Lord, are they who have come up unto this land with an eye single to my glory, according to my commandments."],["D&C",59,2,"For those that live shall inherit the earth, and those that die shall rest from all their labors, and their works shall follow them; and they shall receive a crown in the mansions of my Father, which I have prepared for them."],["D&C",59,3,"Yea, blessed are they whose feet stand upon the land of Zion, who have obeyed my gospel; for they shall receive for their reward the good things of the earth, and it shall bring forth in its strength."],["D&C",59,4,"And they shall also be crowned with blessings from above, yea, and with commandments not a few, and with revelations in their time—they that are faithful and diligent before me."],["D&C",59,5,"Wherefore, I give unto them a commandment, saying thus: Thou shalt love the Lord thy God with all thy heart, with all thy might, mind, and strength; and in the name of Jesus Christ thou shalt serve him."],["D&C",59,6,"Thou shalt love thy neighbor as thyself. Thou shalt not steal; neither commit adultery, nor kill, nor do anything like unto it."],["D&C",59,7,"Thou shalt thank the Lord thy God in all things."],["D&C",59,8,"Thou shalt offer a sacrifice unto the Lord thy God in righteousness, even that of a broken heart and a contrite spirit."],["D&C",59,9,"And that thou mayest more fully keep thyself unspotted from the world, thou shalt go to the house of prayer and offer up thy sacraments upon my holy day;"],["D&C",59,10,"For verily this is a day appointed unto you to rest from your labors, and to pay thy devotions unto the Most High;"],["D&C",59,11,"Nevertheless thy vows shall be offered up in righteousness on all days and at all times;"],["D&C",59,12,"But remember that on this, the Lord's day, thou shalt offer thine oblations and thy sacraments unto the Most High, confessing thy sins unto thy brethren, and before the Lord."],["D&C",59,13,"And on this day thou shalt do none other thing, only let thy food be prepared with singleness of heart that thy fasting may be perfect, or, in other words, that thy joy may be full."],["D&C",59,14,"Verily, this is fasting and prayer, or in other words, rejoicing and prayer."],["D&C",59,15,"And inasmuch as ye do these things with thanksgiving, with cheerful hearts and countenances, not with much laughter, for this is sin, but with a glad heart and a cheerful countenance—"],["D&C",59,16,"Verily I say, that inasmuch as ye do this, the fulness of the earth is yours, the beasts of the field and the fowls of the air, and that which climbeth upon the trees and walketh upon the earth;"],["D&C",59,17,"Yea, and the herb, and the good things which come of the earth, whether for food or for raiment, or for houses, or for barns, or for orchards, or for gardens, or for vineyards;"],["D&C",59,18,"Yea, all things which come of the earth, in the season thereof, are made for the benefit and the use of man, both to please the eye and to gladden the heart;"],["D&C",59,19,"Yea, for food and for raiment, for taste and for smell, to strengthen the body and to enliven the soul."],["D&C",59,20,"And it pleaseth God that he hath given all these things unto man; for unto this end were they made to be used, with judgment, not to excess, neither by extortion."],["D&C",59,21,"And in nothing doth man offend God, or against none is his wrath kindled, save those who confess not his hand in all things, and obey not his commandments."],["D&C",59,22,"Behold, this is according to the law and the prophets; wherefore, trouble me no more concerning this matter."],["D&C",59,23,"But learn that he who doeth the works of righteousness shall receive his reward, even peace in this world, and eternal life in the world to come."],["D&C",59,24,"I, the Lord, have spoken it, and the Spirit beareth record. Amen."],["D&C",60,1,"Behold, thus saith the Lord unto the elders of his church, who are to return speedily to the land from whence they came: Behold, it pleaseth me, that you have come up hither;"],["D&C",60,2,"But with some I am not well pleased, for they will not open their mouths, but they hide the talent which I have given unto them, because of the fear of man. Wo unto such, for mine anger is kindled against them."],["D&C",60,3,"And it shall come to pass, if they are not more faithful unto me, it shall be taken away, even that which they have."],["D&C",60,4,"For I, the Lord, rule in the heavens above, and among the armies of the earth; and in the day when I shall make up my jewels, all men shall know what it is that bespeaketh the power of God."],["D&C",60,5,"But, verily, I will speak unto you concerning your journey unto the land from whence you came. Let there be a craft made, or bought, as seemeth you good, it mattereth not unto me, and take your journey speedily for the place which is called St. Louis."],["D&C",60,6,"And from thence let my servants, Sidney Rigdon, Joseph Smith, Jun., and Oliver Cowdery, take their journey for Cincinnati;"],["D&C",60,7,"And in this place let them lift up their voice and declare my word with loud voices, without wrath or doubting, lifting up holy hands upon them. For I am able to make you holy, and your sins are forgiven you."],["D&C",60,8,"And let the residue take their journey from St. Louis, two by two, and preach the word, not in haste, among the congregations of the wicked, until they return to the churches from whence they came."],["D&C",60,9,"And all this for the good of the churches; for this intent have I sent them."],["D&C",60,10,"And let my servant Edward Partridge impart of the money which I have given him, a portion unto mine elders who are commanded to return;"],["D&C",60,11,"And he that is able, let him return it by the way of the agent; and he that is not, of him it is not required."],["D&C",60,12,"And now I speak of the residue who are to come unto this land."],["D&C",60,13,"Behold, they have been sent to preach my gospel among the congregations of the wicked; wherefore, I give unto them a commandment, thus: Thou shalt not idle away thy time, neither shalt thou bury thy talent that it may not be known."],["D&C",60,14,"And after thou hast come up unto the land of Zion, and hast proclaimed my word, thou shalt speedily return, proclaiming my word among the congregations of the wicked, not in haste, neither in wrath nor with strife."],["D&C",60,15,"And shake off the dust of thy feet against those who receive thee not, not in their presence, lest thou provoke them, but in secret; and wash thy feet, as a testimony against them in the day of judgment."],["D&C",60,16,"Behold, this is sufficient for you, and the will of him who hath sent you."],["D&C",60,17,"And by the mouth of my servant Joseph Smith, Jun., it shall be made known concerning Sidney Rigdon and Oliver Cowdery. The residue hereafter. Even so. Amen."]]);
